from decimal import Decimal

from shop.orders import checkout


def test_checkout_total():
    assert checkout(Decimal("9.50"), 2) == Decimal("24.00")


def test_checkout_with_free_shipping():
    assert checkout(Decimal("30.00"), 2) == Decimal("60.00")

from shop.inventory import Stock, can_fulfill


def test_can_fulfill_in_stock_order():
    assert can_fulfill(Stock("BOOK", 4), 4)


def test_rejects_empty_orders():
    assert not can_fulfill(Stock("BOOK", 4), 0)

from dataclasses import dataclass


@dataclass(frozen=True)
class Stock:
    sku: str
    on_hand: int
    reserved: int = 0


def availability(item: Stock) -> int:
    """Return stock available for new orders."""
    return item.on_hand


def can_fulfill(item: Stock, quantity: int) -> bool:
    return 0 < quantity <= availability(item)
